#define JS_MAX_LOCAL_VARS 65535
#define JS_STACK_SIZE_MAX 65534
#define JS_STRING_LEN_MAX ((1 << 30) - 1)
// 1,024 bytes is about the cutoff point where it starts getting
// more profitable to ref slice than to copy
#define JS_STRING_SLICE_LEN_MAX 1024 // in bytes

/* strings <= this length are not concatenated using ropes. if too
   small, the rope memory overhead becomes high. */
#define JS_STRING_ROPE_SHORT_LEN  512
/* specific threshold for initial rope use */
#define JS_STRING_ROPE_SHORT2_LEN 8192
/* rope depth at which we rebalance */
#define JS_STRING_ROPE_MAX_DEPTH 60

/* Yield-aware collection pacing. A collection is unproductive when it
   reclaimed less than 1/JS_GC_BARREN_FRACTION of the heap or less than
   JS_GC_MIN_WORTH bytes. Consecutive unproductive collections double the
   growth step, up to JS_GC_PACE_MAX_PCT of the live heap; a productive one
   resets the streak. A cap of 0 keeps the unmodified rule. */
#define JS_GC_BARREN_FRACTION     64
#define JS_GC_MIN_WORTH           (256 * 1024)
#define JS_GC_PACE_MAX_PCT        400
#define JS_GC_PACE_STREAK_DEFAULT 8

