/* Small-block "arena" allocator.
   js_{malloc,free,realloc,calloc}_rt serve allocations up to ~512
   bytes from size-classed 4KB arenas carved out of the underlying
   JSMallocFunctions allocator, so the backing allocator (system malloc,
   mimalloc, ...) sees roughly one request per arena refill instead of one per
   object. */

#define JS_ARENA_ALIGN             8
#define JS_ARENA_SIZE              4096
#define JS_ARENA_BLOCK_SIZE_COUNT  31
#define JS_ARENA_MAX_SMALL_SIZE    512
#define JS_ARENA_FREE_NIL          0xffff
/* Upper bound on empty arenas kept for reuse, runtime-wide, so small
   allocations can reuse a block instead of asking the system allocator. */
#define JS_ARENA_EMPTY_MAX         256

#if defined(__SANITIZE_ADDRESS__) || defined(FORCE_GC_AT_MALLOC)
/* Route every allocation through the backing malloc so each block is seen
   individually: ASan can then poison a freed block, and a GC-stress build
   (FORCE_GC_AT_MALLOC) exposes prematurely-freed objects instead of the pool
   silently recycling them. */
#define JS_ARENA_LARGE_BLOCKS_ONLY 1
#else
#define JS_ARENA_LARGE_BLOCKS_ONLY 0
#endif

/* Inline caches. The default is one compact entry per site; a second entry is
   allocated for the function only after a site observes a second shape. */
#ifndef JS_ENABLE_IC
#define JS_ENABLE_IC 1
#endif
/* JS_IC_ENTRIES is the per-site width. The shipping default is four entries;
   an explicit -DJS_IC_ENTRIES=1 retains the cheap monomorphic configuration. */
#ifndef JS_IC_POLY
#define JS_IC_POLY 0
#endif
#ifndef JS_IC_ENTRIES
#if JS_IC_POLY
#define JS_IC_ENTRIES 2
#else
#define JS_IC_ENTRIES 4
#endif
#endif
/* refills that did not stick before a monomorphic/PIC site goes megamorphic */
#ifndef JS_IC_MEGAMORPHIC_MISSES
#define JS_IC_MEGAMORPHIC_MISSES 8
#endif
/* Cache flags: high bits are kind/state, a 13-bit watchpoint epoch, and a
   saturating miss counter. This is the unified entry layout expected by 1095. */
#define JS_IC_FLAG_MEGAMORPHIC 0x80000000u /* site disabled: stop probing/refilling */
#define JS_IC_FLAG_PROTO       0x40000000u /* value lives on shape->proto */
#define JS_IC_FLAG_TRANSITION  0x20000000u /* add-transition (to_shape set) */
#define JS_IC_EPOCH_SHIFT      16
#define JS_IC_EPOCH_MASK       0x1fff0000u /* bits 16..28: proto-watchpoint epoch snapshot */
#define JS_IC_EPOCH_MAX        0x1fffu     /* saturation: stop filling transition entries */
#define JS_IC_MISS_MASK        0x0000ffffu

