static uint64_t qjs_mega_probes, qjs_mega_hits, qjs_mega_fills;
static uint64_t qjs_ic_depth2;
#define QJS_ICSTAT_INC(x) ((x)++)
#else
#define QJS_ICSTAT_INC(x) ((void)0)
#endif
