        int32_t sum;

        if (likely(!__builtin_add_overflow(JS_VALUE_GET_INT(v), imm, &sum)))
            T_SET_NEXT_P(d, js_int32(sum), T_SZ_RRI_S);
        T_SET_NEXT_P(d, js_float64((double)((int64_t)JS_VALUE_GET_INT(v) + imm)),
                     T_SZ_RRI_S);
