                                    JSShapeProperty *hpr;
                                    if (ic[k].offset >= (uint32_t)hsh->prop_count)
                                        break;
                                    hpr = &get_shape_prop(hsh)[ic[k].offset];
                                    if (hpr->atom != atom ||
                                        (hpr->flags & JS_PROP_TMASK))
                                        break;
